export function getTranslatedSparePartName(name: string, language: string): string {
  // First, check if the input name is already a key in the translations table
  const translations = sparePartNameTranslations[name];
  if (translations && translations[language]) {
    return translations[language];
  }
  
  // If the input is Chinese, find the English name and translate to target language
  if (language !== 'zh') {
    for (const [englishName, translationMap] of Object.entries(sparePartNameTranslations)) {
      if (translationMap['zh'] === name) {
        // Found the Chinese name, return the translation in target language
        const targetTranslation = translationMap[language];
        if (targetTranslation) {
          return targetTranslation;
        }
      }
    }
  }
  
  // If not found, try to find by English value
  if (language !== 'en') {
    for (const [key, trans] of Object.entries(sparePartNameTranslations)) {
      // Check if the English value matches the input name
      if (trans['en'] === name && trans[language]) {
        return trans[language];
      }
    }
  }
  
  return name;
}

export function getTranslatedSparePartDescription(description: string, language: string): string {
  // First try to find the description in the translations table (for Chinese keys)
  const translations = sparePartDescriptionTranslations[description];
  if (translations && translations[language]) {
    return translations[language];
  }
  // If not found and language is not 'en', try to find the English version and return it
  if (language !== 'en' && translations && translations['en']) {
    return translations['en'];
  }
  // If the description is in English and not found in translations, look for a matching Chinese key
  // by checking all keys in the translation table
  if (language !== 'en') {
    for (const [key, trans] of Object.entries(sparePartDescriptionTranslations)) {
      // Check if the English value matches the input description
      if (trans['en'] === description && trans[language]) {
        return trans[language];
      }
    }
  }
  return description;
}

export function getTranslatedSparePartCategory(category: string, language: string): string {
  const translations = sparePartCategoryTranslations[category];
  if (translations && translations[language]) {
    return translations[language];
  }
  // If not found, try to find the English key and return its translation in the target language
  if (language !== 'en') {
    for (const [key, trans] of Object.entries(sparePartCategoryTranslations)) {
      // Check if the English value matches the input category
      if (trans['en'] === category && trans[language]) {
        return trans[language];
      }
    }
  }
  return category;
}

