export function getTranslatedLiuGongMachineType(type: string, language: string): string {
  const translations = liugongMachineTypeTranslations[type];
  if (!translations) return type;
  return translations[language] || translations['en'] || type;
}

export function getTranslatedLiuGongMachineDescription(description: string, language: string): string {
  const translations = liugongMachineDescriptionTranslations[description];
  if (!translations) return description;
  return translations[language] || translations['en'] || description;
}

